function metricHtml(m={}){return[['CPU',m.cpu_percent],['Память',m.ram_used_percent],['Диск',m.disk_used_percent]].map(([name,v])=>{v=Math.max(0,Math.min(100,Number(v)||0));return'<div class="metric"><div class="metric-name">'+name+'</div><div class="metric-value">'+Math.round(v)+'%</div><div class="metric-bar"><i style="width:'+v+'%"></i></div></div>'}).join('')}
function age(iso){if(!iso)return'нет данных';const sec=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);return sec<60?Math.round(sec)+' сек назад':sec<3600?Math.floor(sec/60)+' мин назад':Math.floor(sec/3600)+' ч назад'}
function versionAtLeast(value,wanted){const a=String(value||'0').split('.').map(Number),b=wanted.split('.').map(Number);for(let i=0;i<3;i++){if((a[i]||0)>(b[i]||0))return true;if((a[i]||0)<(b[i]||0))return false}return true}
function isPc(item){return /pc|windows/i.test(String(item.source_type||'')+' '+String(item.last_payload?.platform||''))}
function valueText(value,suffix=''){const n=Number(value);return Number.isFinite(n)?Math.round(n*10)/10+suffix:'—'}
function deviceHtml(list,actions=false){return(list||[]).map(item=>{const pc=isPc(item),old=pc&&!versionAtLeast(item.agent_version,'0.6.0'),p=item.last_payload||{},m=p.metrics||{},a=p.archive_status||{},cmd=item.latest_command||{},cmdResult=cmd.result||{},archiveText=item.archive_enabled?((a.pending_retry?'повторная доставка':'синхронизирован')+' · '+valueText(a.cursor,' событий')+(a.free_bytes?' · '+valueText(a.free_bytes/1073741824,' ГБ свободно'):'')):'выключен',versionText='агент '+esc(item.agent_version||'0.0.0')+(item.agent_revision?' · '+esc(String(item.agent_revision).slice(0,10)):'')+(p.server_version_seen?' · сервер '+esc(p.server_version_seen):'');return'<div class="row"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7">'+(pc?'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>':'<rect x="4" y="3" width="16" height="7" rx="2"/><rect x="4" y="14" width="16" height="7" rx="2"/>')+'</svg><div class="row-main"><div class="row-title">'+esc(item.source_name)+'</div><div class="row-sub">v'+esc(item.agent_version||'0.0.0')+' · '+age(item.last_seen_at)+'</div>'+(old?'<div class="warning">Для блокировки установите свежий агент.</div>':'')+(actions&&state.owner?'<div class="device-actions"><button class="btn blue agent-command" data-source="'+esc(item.source_name)+'" data-command="update">Обновить</button><button class="btn agent-command" data-source="'+esc(item.source_name)+'" data-command="restart">Перезапустить</button>'+(pc?'<button class="btn danger agent-command" data-source="'+esc(item.source_name)+'" data-command="lock">Заблокировать экран</button><button class="btn archive-toggle" data-source="'+esc(item.source_name)+'" data-enabled="'+(!item.archive_enabled)+'">'+(item.archive_enabled?'Не хранить архив':'Хранить архив здесь')+'</button>':'')+'</div>':'')+(actions?'<details class="agent-details"><summary>Статистика агента</summary><div class="agent-grid"><div class="agent-stat"><span>CPU</span><b>'+valueText(m.cpu_percent,'%')+'</b></div><div class="agent-stat"><span>Память</span><b>'+valueText(m.ram_used_percent,'%')+' · '+valueText(m.ram_used_mb,' МБ')+'</b></div><div class="agent-stat"><span>Диск</span><b>'+valueText(m.disk_used_percent,'%')+' · '+valueText(m.disk_used_gb,' ГБ')+'</b></div><div class="agent-stat"><span>Сеть</span><b>↓ '+valueText(m.net_rx_mb,' МБ')+' · ↑ '+valueText(m.net_tx_mb,' МБ')+'</b></div><div class="agent-stat"><span>Задержка</span><b>'+valueText(m.heartbeat_latency_ms,' мс')+'</b></div><div class="agent-stat"><span>Heartbeat</span><b>'+esc(age(item.last_seen_at))+'</b></div><div class="agent-stat wide"><span>Версии</span><b>'+versionText+'</b></div><div class="agent-stat"><span>Активность</span><b>'+esc(p.active_app||'нет данных')+'</b></div><div class="agent-stat"><span>Локальный архив</span><b>'+archiveText+'</b></div><div class="agent-stat wide"><span>Последняя команда</span><b>'+(cmd.command?esc(cmd.command+' · '+cmd.status+(cmdResult.message?' · '+cmdResult.message:'')):'нет команд')+'</b></div>'+(p.last_error?'<div class="agent-stat wide error"><span>Последняя ошибка'+(p.last_error_at?' · '+esc(age(p.last_error_at)):'')+'</span><b>'+esc(p.last_error)+'</b></div>':'')+(a.last_error?'<div class="agent-stat wide error"><span>Ошибка синхронизации архива</span><b>'+esc(a.last_error)+'</b></div>':'')+'</div></details>':'')+'</div><span class="status '+(item.is_online?'':'off')+'">'+(item.is_online?'В сети':'Offline')+'</span></div>'}).join('')||'<div class="empty">Устройства ещё не подключены.</div>'}
const agentAttentionLabels={offline:'нет связи',high_cpu:'высокая загрузка CPU',high_ram:'заканчивается память',low_disk:'заканчивается место',agent_error:'ошибка агента',archive_error:'ошибка архива',update_available:'доступно обновление'};
function enhanceAgentActions(list=[]){document.querySelectorAll('#deviceList .row').forEach((row,index)=>{const item=list[index],actions=row.querySelector('.device-actions');if(!item)return;const reasons=(item.attention_reasons||[]).map(x=>agentAttentionLabels[x]||x);if(reasons.length){const note=document.createElement('div');note.className='attention-note';note.textContent='Требует внимания: '+reasons.join(', ');row.querySelector('.row-main')?.insertBefore(note,row.querySelector('.agent-details'));const badge=row.querySelector('.status');if(item.is_online&&badge){badge.classList.add('warn');badge.textContent='Внимание'}}if(!actions||actions.dataset.enhanced==='1')return;actions.dataset.enhanced='1';const source=esc(item.source_name),button=(command,label,kind='')=>'<button class="btn '+kind+' agent-command" data-source="'+source+'" data-command="'+command+'">'+label+'</button>';let html=button('ping','Проверить связь')+button('check_update','Проверить обновление')+'<button class="btn agent-command-history" data-source="'+source+'">История команд</button>';if(isPc(item))html+=button('sleep','Сон','danger')+button('reboot','Перезагрузить ПК','danger')+button('shutdown','Выключить ПК','danger')+button('open_archive','Открыть архив')+button('cleanup_archive','Очистить медиа','danger');actions.insertAdjacentHTML('afterbegin',html);actions.querySelector('.agent-command-history').onclick=event=>loadAgentCommandHistory(item.source_name,event.currentTarget.closest('.row'))})}
function filteredAgents(){const list=state.boot?.sources||[];if(state.agentFilter==='online')return list.filter(x=>x.is_online);if(state.agentFilter==='offline')return list.filter(x=>!x.is_online);if(state.agentFilter==='attention')return list.filter(x=>x.requires_attention);if(state.agentFilter==='update')return list.filter(x=>x.requires_update);return list}
function renderDeviceList(){const list=filteredAgents();$('deviceList').innerHTML=deviceHtml(list,true);enhanceAgentActions(list);bindCommands();document.querySelectorAll('[data-agent-filter]').forEach(btn=>btn.classList.toggle('on',btn.dataset.agentFilter===state.agentFilter))}
function renderSystemStatus(items={}){const labels={backend:'Backend',database:'База данных',telegram_bot:'Telegram-бот',public_site:'Публичный сайт',interface:'Интерфейс'};$('systemStatusList').innerHTML=Object.entries(items).map(([key,item])=>{const ok=!!item.available,label=labels[key]||key,detail=[item.version,item.http_status?'HTTP '+item.http_status:'',item.latency_ms!=null?item.latency_ms+' мс':''].filter(Boolean).join(' · ');return'<div class="row"><div class="row-main"><div class="row-title">'+esc(label)+'</div>'+(detail?'<div class="row-sub">'+esc(detail)+'</div>':'')+'</div><span class="status '+(ok?'':'off')+'">'+esc(ok?'Работает':item.status||'Недоступен')+'</span></div>'}).join('')||'<div class="empty">Состояние компонентов недоступно.</div>'}
const notificationLabels={agent_connected:'Новый агент',agent_offline:'Агент отключился',agent_recovered:'Агент вернулся',high_load:'Высокая нагрузка',low_disk:'Мало места',archive_error:'Ошибка архива',media_error:'Ошибка медиа',update_available:'Доступно обновление',update_completed:'Обновление завершено',update_rollback:'Обновление откатилось',dangerous_command:'Опасная команда',new_login:'Новый вход',passkey_registered:'Новый Passkey',pair_code_created:'Код привязки',auth_failed:'Ошибка входа',automation_rule:'Правило автоматизации'};
function renderNotificationPreferences(list=[],pushSupported=false){$('notificationPreferences').innerHTML=list.map(item=>'<div class="preference-row" data-preference="'+esc(item.event_type)+'"><div><div class="row-title">'+esc(notificationLabels[item.event_type]||item.event_type)+'</div><div class="channel-list"><label><input type="checkbox" data-channel="internal" '+(item.channels.includes('internal')?'checked':'')+'> Внутри XASS</label><label><input type="checkbox" data-channel="telegram" '+(item.channels.includes('telegram')?'checked':'')+'> Telegram</label><label title="'+(pushSupported?'Push доступен в установленном PWA':'Администратор должен настроить VAPID на сервере')+'"><input type="checkbox" data-channel="push" '+(item.channels.includes('push')?'checked':'')+(pushSupported?'':' disabled')+'> Push</label><label><input type="checkbox" data-quiet '+(item.quiet_hours?'checked':'')+'> соблюдать тихие часы</label></div></div><div class="preference-controls"><select class="input" data-priority><option value="info" '+(item.priority==='info'?'selected':'')+'>info</option><option value="success" '+(item.priority==='success'?'selected':'')+'>success</option><option value="warning" '+(item.priority==='warning'?'selected':'')+'>warning</option><option value="critical" '+(item.priority==='critical'?'selected':'')+'>critical</option></select><button class="btn notification-pref-save">Сохранить</button></div></div>').join('');document.querySelectorAll('.notification-pref-save').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-preference]'),channels=[...row.querySelectorAll('[data-channel]:checked')].map(x=>x.dataset.channel);btn.disabled=true;try{const r=await api('notifications/preferences',{method:'PUT',body:{event_type:row.dataset.preference,channels,priority:row.querySelector('[data-priority]').value,quiet_hours:row.querySelector('[data-quiet]').checked}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось сохранить');toast('Настройка уведомлений сохранена')}catch(e){toast(e.message)}finally{btn.disabled=false}})}
function renderNotifications(data={}){const items=data.items||[];state.pushPublicKey=data.push_public_key||'';$('notificationCount').textContent=data.unread_count?data.unread_count+' новых':'';$('notificationList').innerHTML=items.map(item=>'<div class="row notification-item '+(item.status==='new'||item.status==='action'?'new':'')+'"><span class="notification-priority '+esc(item.priority)+'"></span><div class="row-main"><div class="row-title">'+esc(item.title)+'</div><div class="row-sub">'+esc(item.message)+'</div><div class="log-meta" style="margin-top:7px"><span>'+esc(notificationLabels[item.event_type]||item.event_type)+(item.device?' · '+esc(item.device):'')+'</span><span>'+new Date(item.created_at).toLocaleString('ru-RU')+'</span></div><div class="notification-actions">'+(item.status!=='read'?'<button class="btn notification-read" data-id="'+item.id+'">Прочитано</button>':'')+'<button class="btn notification-hide" data-id="'+item.id+'">Скрыть</button></div></div><span class="status '+(item.status==='action'?'warn':'')+'">'+esc(item.status==='action'?'Действие':item.status==='read'?'Прочитано':'Новое')+'</span></div>').join('')||'<div class="empty">Здесь пока спокойно — новых событий нет.</div>';renderNotificationPreferences(data.preferences||[],!!data.push_supported);refreshPushButton(!!data.push_supported);document.querySelectorAll('.notification-read').forEach(btn=>btn.onclick=()=>api('notifications/'+btn.dataset.id+'/read',{method:'POST'}).then(()=>loadNotifications()));document.querySelectorAll('.notification-hide').forEach(btn=>btn.onclick=()=>api('notifications/'+btn.dataset.id,{method:'DELETE'}).then(()=>loadNotifications()))}
function vapidKeyBytes(value){const padding='='.repeat((4-value.length%4)%4),base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes}
async function refreshPushButton(serverReady){const button=$('pushEnableBtn');if(!serverReady||!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){button.style.display='none';return}button.style.display='block';try{const registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.getSubscription();state.pushSubscription=subscription;button.textContent=subscription?'Отключить push на этом устройстве':'Включить push в PWA';button.classList.toggle('danger',!!subscription)}catch(e){button.textContent='Push недоступен в этом режиме'}}
$('pushEnableBtn').onclick=async function(){this.disabled=true;try{const registration=await navigator.serviceWorker.ready,current=await registration.pushManager.getSubscription();if(current){const endpoint=current.endpoint,r=await api('push/subscribe',{method:'DELETE',body:{endpoint}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось удалить подписку');await current.unsubscribe();toast('Push на этом устройстве отключён');await refreshPushButton(true);return}if(!state.pwa&&!matchMedia('(display-mode: standalone)').matches)throw new Error('Сначала добавьте XASS на экран Домой и откройте установленное приложение');const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Разрешение на уведомления не выдано');const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidKeyBytes(state.pushPublicKey)}),r=await api('push/subscribe',{method:'POST',body:subscription.toJSON()});if(!r.data?.ok){await subscription.unsubscribe();throw new Error(r.data?.detail||'Сервер не сохранил push-подписку')}toast('Push-уведомления включены');await refreshPushButton(true)}catch(e){toast(e.message||'Push недоступен')}finally{this.disabled=false}};
async function loadNotifications(){try{const query=state.notificationFilter?'?status_filter='+encodeURIComponent(state.notificationFilter):'',r=await api('notifications'+query);if(!r.data?.ok)throw new Error(r.data?.detail||'Уведомления недоступны');renderNotifications(r.data)}catch(e){$('notificationList').innerHTML='<div class="empty">'+esc(e.message||'Не удалось загрузить уведомления')+' <button class="btn" id="notificationsRetry">Повторить</button></div>';$('notificationsRetry')?.addEventListener('click',loadNotifications)}}
