function renderScenarioDevices(){const devices=(state.boot?.sources||[]).filter(isPc);$('scenarioDevices').innerHTML=devices.map(x=>'<label><input type="checkbox" data-scenario-device="'+esc(x.source_name)+'"> '+esc(x.source_name)+'</label>').join('')||'<span class="muted">Сначала подключите Windows-агент.</span>'}
function renderScenarios(list=[]){const actionNames={away_on:'Не в сети',away_off:'Вернулся',quiet_on:'Тихие часы',quiet_off:'Обычный режим',check_all:'Проверка ПК',lock_all:'Блокировка ПК',update_all:'Обновление ПК'};$('scenarioList').innerHTML=(list||[]).map(x=>{const meta=[(x.actions||[]).map(a=>actionNames[a]||a).join(' → '),(x.devices||[]).length?(x.devices||[]).join(', '):'все устройства',x.delay_sec?x.delay_sec+' сек. между шагами':'',x.schedule?'ежедневно '+x.schedule:''].filter(Boolean).join(' · ');return'<div class="row"><span class="notification-priority" style="background:'+esc(x.color||'#376dff')+'"></span><div class="row-main"><div class="row-title">'+esc(x.name)+(x.enabled===false?' · выключен':'')+'</div><div class="row-sub">'+esc(meta)+'</div><div class="scenario-history-panel" data-history-panel="'+esc(x.id)+'"></div></div><div class="device-actions"><button class="btn blue scenario-run" '+(x.enabled===false?'disabled':'')+' data-id="'+esc(x.id)+'" data-danger="'+((x.actions||[]).some(a=>a==='lock_all'||a==='update_all'))+'">Запустить</button><button class="btn scenario-history" data-id="'+esc(x.id)+'">История</button>'+(!x.builtin?'<button class="btn scenario-toggle" data-id="'+esc(x.id)+'">'+(x.enabled===false?'Включить':'Выключить')+'</button><button class="btn danger scenario-delete" data-id="'+esc(x.id)+'">Удалить</button>':'')+'</div></div>'}).join('')||'<div class="empty">Сценариев пока нет.</div>';document.querySelectorAll('.scenario-run').forEach(button=>button.onclick=()=>ask('Запустить сценарий?',ok=>ok&&runScenario(button.dataset.id,button.dataset.danger==='true')));document.querySelectorAll('.scenario-history').forEach(button=>button.onclick=()=>loadScenarioHistory(button.dataset.id));document.querySelectorAll('.scenario-toggle').forEach(button=>button.onclick=async()=>{const item=(state.boot.scenarios||[]).find(x=>x.id===button.dataset.id);if(!item)return;const r=await api('scenarios',{method:'POST',body:{id:item.id,name:item.name,icon:item.icon||'bolt',color:item.color||'#376dff',devices:item.devices||[],actions:item.actions||[],delay_sec:item.delay_sec||0,schedule:item.schedule||'',enabled:item.enabled===false}});if(r.data?.ok){state.boot.scenarios=r.data.scenarios||[];renderScenarios(state.boot.scenarios)}else toast(r.data?.detail||'Не удалось изменить сценарий')});document.querySelectorAll('.scenario-delete').forEach(button=>button.onclick=()=>ask('Удалить пользовательский сценарий?',ok=>ok&&api('scenarios/'+encodeURIComponent(button.dataset.id),{method:'DELETE'}).then(r=>{if(r.data?.ok){state.boot.scenarios=r.data.scenarios||[];renderScenarios(state.boot.scenarios);toast('Сценарий удалён')}else toast(r.data?.detail||'Не удалось удалить')})))}
async function loadScenarioHistory(id){const panel=document.querySelector('[data-history-panel="'+CSS.escape(id)+'"]');if(!panel)return;panel.innerHTML='<div class="row-sub">Загрузка истории…</div>';try{const r=await api('scenarios/'+encodeURIComponent(id)+'/history');if(!r.data?.ok)throw new Error(r.data?.detail||'История недоступна');panel.innerHTML=(r.data.history||[]).map(item=>{const p=item.payload||{},steps=p.steps||[];return'<div class="log"><div class="log-meta"><span>'+esc(p.channel||'XASS')+'</span><span>'+new Date(item.created_at).toLocaleString('ru-RU')+'</span></div><div class="log-text">'+esc(steps.map(x=>(actionNamesGlobal[x.action]||x.action)+': '+x.status).join(' · ')||'Выполнено')+'</div></div>'}).join('')||'<div class="row-sub">Запусков ещё не было.</div>'}catch(e){panel.innerHTML='<div class="warning">'+esc(e.message)+'</div>'}}
