$('downloadInstallerBtn').onclick=async function(){if(demo)return toast('Демо: загрузка XASS-Setup.exe');this.disabled=true;const fallback=state.boot?.windows_installer?.fallback_url||'';try{const result=await api('agent-installer/ticket');if(!result.data?.ok)throw new Error(result.data?.detail||'Локальный установщик недоступен');const streamUrl='/proxy.php?_binary=1&_p='+encodeURIComponent(result.data.download_path),a=document.createElement('a');a.href=streamUrl;a.download=state.boot?.windows_installer?.file_name||'XASS-Setup.exe';document.body.appendChild(a);a.click();a.remove();toast('Загрузка установщика началась')}catch(e){if(fallback){if(tg?.openLink)tg.openLink(fallback);else window.open(fallback,'_blank');toast('Открываю резервную загрузку GitHub')}else toast(e.message||'Не удалось скачать установщик')}finally{setTimeout(()=>renderInstaller(state.boot.windows_installer||{}),700)}};
function loadUpdateStatus(){api('update-status').then(r=>{const d=r.data||{};$('updateResult').style.display='block';$('updateResult').textContent=d.has_updates?'Доступно изменений: '+(d.commits||[]).length:'Сервер обновлён';$('runUpdateBtn').disabled=!d.has_updates}).catch(e=>toast(e.message||'Не удалось проверить обновление'))}$('checkUpdateBtn').onclick=loadUpdateStatus;async function runServerUpdate(){const button=$('runUpdateBtn');button.disabled=true;$('updateResult').style.display='block';$('updateResult').textContent='Подтверждаю и устанавливаю обновление…';try{const proof=await passkeyAction('server:update'),r=await api('run-update',{method:'POST',headers:{'X-XASS-Action-Proof':proof}});if(!r.data?.ok)throw new Error(r.data?.error||r.data?.detail||'Обновление не выполнено');$('updateResult').textContent='Готово\n'+(r.data.steps||[]).join('\n')}catch(e){$('updateResult').textContent='Ошибка: '+(e.message||'нет связи')}finally{button.disabled=false}}$('runUpdateBtn').onclick=()=>ask('Установить обновление сервера? XASS перезапустит только нужный сервис.',ok=>ok&&runServerUpdate());$('restartServerBtn').onclick=()=>ask('Перезапустить backend XASS?',async ok=>{if(!ok)return;try{const proof=await passkeyAction('server:restart'),r=await api('restart',{method:'POST',headers:{'X-XASS-Action-Proof':proof}});if(!r.data?.ok)throw new Error(r.data?.detail||'Перезапуск не запланирован');toast('Перезапуск запланирован')}catch(e){toast(e.message||'Не удалось перезапустить сервер')}});
function loadLogs(){api('logs?limit=30').then(r=>{$('logList').innerHTML=(r.data?.logs||[]).map(x=>'<div class="log"><div class="log-meta"><span>'+esc(x.chat_title||x.from_username||'XASS')+' · '+esc(x.direction||'')+'</span><span>'+(x.date?new Date(x.date).toLocaleString('ru-RU'):'')+'</span></div><div class="log-text">'+esc(x.text||'')+'</div></div>').join('')||'<div class="empty">Сообщений нет.</div>'})}$('logsBtn').onclick=loadLogs;
function chatInitials(value){return String(value||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'?'}
function filterConversations(){const q=$('conversationSearch').value.trim().toLowerCase(),rows=state.conversations.filter(x=>(!q||String(x.title+' '+x.last_text).toLowerCase().includes(q))&&(!state.deletedOnly||Number(x.deleted)>0)&&(!state.editedOnly||Number(x.edited)>0)&&(!state.mediaOnly||Number(x.media)>0));$('conversationList').innerHTML=rows.map(x=>'<button class="chat-row" data-chat="'+x.chat_id+'"><span class="chat-avatar" data-avatar-chat="'+x.chat_id+'" aria-hidden="true">'+esc(chatInitials(x.title))+'</span><span><span class="chat-title">'+(x.pinned?'📌 ':'')+esc(x.title)+'</span><span class="chat-preview">'+esc(x.last_text||'Нет текста')+'</span></span><span><span class="section-note">'+esc(x.count)+'</span>'+(x.deleted?'<span class="chat-badge"> · удалено '+esc(x.deleted)+'</span>':'')+(x.edited?'<span class="chat-badge"> · изм. '+esc(x.edited)+'</span>':'')+(x.media?'<span class="chat-badge"> · медиа '+esc(x.media)+'</span>':'')+'<span class="chat-pin" role="button" tabindex="0" data-pin-chat="'+x.chat_id+'" data-pinned="'+(!x.pinned)+'">'+(x.pinned?'Открепить':'Закрепить')+'</span></span></button>').join('')||'<div class="empty">Диалоги не найдены.</div>';document.querySelectorAll('.chat-row').forEach(row=>row.onclick=event=>{if(event.target.closest('[data-pin-chat]'))return;openConversation(Number(row.dataset.chat))});document.querySelectorAll('[data-pin-chat]').forEach(pin=>pin.onclick=async event=>{event.stopPropagation();const r=await api('conversations/'+pin.dataset.pinChat+'/pin',{method:'POST',body:{pinned:pin.dataset.pinned==='true'}});if(r.data?.ok)loadConversations();else toast(r.data?.detail||'Не удалось закрепить')});loadConversationAvatars()}
async function loadConversationAvatars(){for(const url of state.avatarObjectUrls)URL.revokeObjectURL(url);state.avatarObjectUrls=[];const headers={};if(initData)headers['X-Telegram-Init-Data']=initData;await Promise.all([...document.querySelectorAll('[data-avatar-chat]')].map(async holder=>{try{const response=await fetch('/proxy.php?_passthrough=1&_p='+encodeURIComponent('/api/mini/conversations/'+holder.dataset.avatarChat+'/avatar'),{headers,credentials:'include'});if(!response.ok)return;const blob=await response.blob();if(!blob.type.startsWith('image/'))return;const url=URL.createObjectURL(blob);state.avatarObjectUrls.push(url);holder.innerHTML='<img src="'+url+'" alt="">'}catch(error){console.debug('XASS avatar unavailable',error)}}))}
let conversationsPromise=null;async function loadConversations(){if(conversationsPromise)return conversationsPromise;conversationsPromise=(async()=>{try{const r=await api('conversations');if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось загрузить диалоги');state.conversations=r.data.chats||[];renderArchiveSummary(r.data.archive||{});filterConversations()}catch(e){if(!state.conversations.length)$('conversationList').innerHTML='<div class="empty">'+esc(e.message||'Архив временно недоступен')+'</div>';else toast(e.message||'Не удалось обновить архив')}finally{conversationsPromise=null}})();return conversationsPromise}
async function loadThreadMedia(node){if(node.dataset.loaded||node.dataset.loading)return;node.dataset.loading='1';node.textContent='Загружаю медиа…';try{const headers={};if(initData)headers['X-Telegram-Init-Data']=initData;const response=await fetch('/proxy.php?_binary=1&_p='+encodeURIComponent('/api/mini/media/'+node.dataset.mediaId),{headers,credentials:'include'});if(!response.ok||Number(response.headers.get('X-XASS-Status')||response.status)>=400)throw new Error('media');const blob=await response.blob(),url=URL.createObjectURL(blob),mime=node.dataset.mime||blob.type||'';state.mediaObjectUrls.push(url);node.dataset.loaded='1';if(mime.startsWith('image/'))node.innerHTML='<img class="media-preview" alt="Медиа сообщения">';else if(mime.startsWith('video/'))node.innerHTML='<video class="media-preview" controls preload="metadata"></video>';else if(mime.startsWith('audio/'))node.innerHTML='<audio class="media-preview" controls preload="metadata"></audio>';else node.innerHTML='<a class="media-download" download>Скачать файл</a>';node.firstElementChild.src=url}catch(e){node.textContent='Медиа уже недоступно в Telegram; локальная копия остаётся на выбранных ПК.'}finally{delete node.dataset.loading}}
function bindThreadMedia(reset=false){if(reset){state.mediaObjectUrls.forEach(URL.revokeObjectURL);state.mediaObjectUrls=[]}document.querySelectorAll('[data-media-id]:not([data-loaded])').forEach(node=>node.onclick=()=>loadThreadMedia(node))}
function messageBubble(m){return'<div class="bubble '+(m.direction==='outgoing'?'out ':'')+(m.deleted?'deleted':'')+'"><div class="bubble-meta">'+(m.date?new Date(m.date).toLocaleString('ru-RU'):'')+(m.from_username?' · @'+esc(m.from_username):'')+(m.forwarded_from?' · <span class="forwarded-pill">переслано от '+esc(m.forwarded_from)+'</span>':'')+(m.deleted?' · <span class="deleted-pill">удалено</span>':'')+(m.edited?' · изменено':'')+(m.media_group_id?' · альбом '+esc(m.media_group_id):'')+'</div>'+(m.reply?'<div class="bubble-reply">Ответ '+(m.reply.from_username?'@'+esc(m.reply.from_username)+' · ':'')+esc(m.reply.text||'Сообщение недоступно')+'</div>':'')+'<div class="bubble-text">'+esc(m.text||'Медиа / сообщение без текста')+'</div>'+(m.reactions?.length?'<div class="channel-list">'+m.reactions.map(x=>'<span>'+esc(x.reaction||x)+' '+(x.actor?'· '+x.actor:'')+'</span>').join('')+'</div>':'')+(m.media?.length?'<div class="bubble-media">Файлов: '+m.media.length+' · постоянные копии находятся на выбранных ПК‑агентах</div><div class="bubble-media-files">'+m.media.map(file=>'<button class="media-download" type="button" data-media-id="'+esc(file.id)+'" data-mime="'+esc(file.mime_type||'')+'">Открыть '+esc(file.type||'медиа')+'</button>').join('')+'</div>':'')+(m.revisions?.length>1?'<details class="agent-details"><summary>История изменений</summary>'+m.revisions.map(x=>'<div class="log"><div class="log-meta">'+esc(x.event)+' · '+new Date(x.date).toLocaleString('ru-RU')+'</div><div class="log-text">'+esc(x.text||'—')+'</div></div>').join('')+'</details>':'')+'</div>'}
async function openConversation(chatId,before=0){const prepend=before>0,r=await api('conversations/'+encodeURIComponent(chatId)+'?limit=150&before='+before+'&deleted_only='+(state.deletedOnly?'true':'false')+'&edited_only='+(state.editedOnly?'true':'false')+'&media_only='+(state.mediaOnly?'true':'false'));if(!r.data?.ok)return toast(r.data?.detail||'Не удалось открыть переписку');state.activeChat=chatId;const chat=state.conversations.find(x=>Number(x.chat_id)===chatId),messages=r.data.messages||[],html=messages.map(messageBubble).join('');$('threadTitle').textContent=chat?.title||String(chatId);$('conversationList').style.display='none';$('conversationThread').classList.add('show');if(prepend)$('threadMessages').insertAdjacentHTML('afterbegin',html);else $('threadMessages').innerHTML=html||'<div class="empty">Сообщений здесь пока нет.</div>';state.threadBefore=messages[0]?.id||state.threadBefore||0;state.threadHasMore=!!r.data.has_more&&!!messages.length;$('threadMore').style.display=state.threadHasMore?'block':'none';bindThreadMedia(!prepend)}
$('threadMore').onclick=()=>state.activeChat&&state.threadBefore&&openConversation(state.activeChat,state.threadBefore);$('threadBack').onclick=()=>{$('conversationThread').classList.remove('show');$('conversationList').style.display='block';state.mediaObjectUrls.forEach(URL.revokeObjectURL);state.mediaObjectUrls=[];state.activeChat=null;state.threadBefore=0};$('conversationSearch').addEventListener('input',filterConversations);$('conversationsRefresh').onclick=loadConversations;function toggleConversationFilter(key,button,label){state[key]=!state[key];button.classList.toggle('blue',state[key]);button.textContent=state[key]?'Показаны: '+label:label;state.activeChat?openConversation(state.activeChat):filterConversations()}$('deletedOnlyBtn').onclick=()=>toggleConversationFilter('deletedOnly',$('deletedOnlyBtn'),'Удалённые');$('editedOnlyBtn').onclick=()=>toggleConversationFilter('editedOnly',$('editedOnlyBtn'),'Изменённые');$('mediaOnlyBtn').onclick=()=>toggleConversationFilter('mediaOnly',$('mediaOnlyBtn'),'С медиа');
async function registerPasskey(){if(!window.PublicKeyCredential)return toast('Этот браузер или режим открытия не поддерживает Passkey. Откройте XASS в Safari, Chrome или Edge по HTTPS.');const button=$('registerPasskeyBtn');button.disabled=true;try{const start=await pwaApi('passkeys/register/options',{method:'POST'});if(start.status!==200||!start.data?.ok)throw new Error(start.data?.detail||'Не удалось начать проверку — убедитесь, что XASS открыт по HTTPS');const credential=await navigator.credentials.create({publicKey:prepareCredentialOptions(start.data.options)}),automaticName=/iPhone|iPad/i.test(navigator.userAgent)?'Face ID на iPhone':/Windows/i.test(navigator.userAgent)?'Windows Hello':'Passkey устройства',name=$('passkeyDeviceName').value.trim()||automaticName,done=await pwaApi('passkeys/register/verify',{method:'POST',body:{transaction:start.data.transaction,credential:serializeCredential(credential),name}});if(done.status!==200||!done.data?.ok)throw new Error(done.data?.detail||'Не удалось сохранить Passkey');$('passkeyDeviceName').value='';toast('Face ID / Passkey добавлен');await loadBoot()}catch(e){if(e?.name!=='NotAllowedError')toast(e.message||'Регистрация отменена')}finally{button.disabled=false}}$('registerPasskeyBtn').onclick=registerPasskey;
function openQuoteEditor(row,item){row.innerHTML='<div class="quote-edit"><input class="input" value="'+esc(item.text)+'" maxlength="2000"><div class="toolbar" style="margin-top:8px"><button class="btn primary quote-save">Сохранить</button><button class="btn quote-cancel">Отмена</button></div></div>';const input=row.querySelector('input');input.focus();input.setSelectionRange(input.value.length,input.value.length);row.querySelector('.quote-cancel').onclick=loadQuotes;row.querySelector('.quote-save').onclick=async()=>{const text=input.value.trim();if(!text)return toast('Цитата не может быть пустой');const r=await api('quotes/'+encodeURIComponent(item.id),{method:'PUT',body:{text}});if(r.data?.ok){toast('Цитата обновлена');loadQuotes()}else toast(r.data?.detail||'Не удалось сохранить')}}
function renderQuotes(list=[]){$('quotesCount').textContent=list.length+' шт.';$('quoteList').innerHTML=list.map((x,index)=>'<div class="quote" data-id="'+esc(x.id)+'"><div class="quote-text">'+esc(x.text)+'</div><div class="quote-actions"><button class="btn quote-move" data-direction="up" type="button" aria-label="Поднять цитату" '+(index===0?'disabled':'')+'>↑</button><button class="btn quote-move" data-direction="down" type="button" aria-label="Опустить цитату" '+(index===list.length-1?'disabled':'')+'>↓</button><button class="btn quote-edit-btn" type="button">Изменить</button><button class="btn danger quote-delete" type="button">Удалить</button></div></div>').join('')||'<div class="empty">Цитат пока нет. Добавьте первую — она сразу появится на сайте.</div>';if(list[0])$('siteQuote').value=list[0].text;document.querySelectorAll('#quoteList .quote').forEach((row,index)=>{const item=list[index];row.querySelector('.quote-edit-btn').onclick=()=>openQuoteEditor(row,item);row.querySelectorAll('.quote-move').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const r=await api('quotes/'+encodeURIComponent(item.id)+'/move',{method:'POST',body:{direction:button.dataset.direction}});if(!r.data?.ok)throw new Error(r.data?.detail||'Не удалось изменить порядок');renderQuotes(r.data.quotes||[])}catch(e){button.disabled=false;toast(e.message)}});row.querySelector('.quote-delete').onclick=()=>ask('Удалить эту цитату?',ok=>ok&&api('quotes/'+encodeURIComponent(item.id),{method:'DELETE'}).then(r=>{if(r.data?.ok){toast('Цитата удалена');renderQuotes(r.data.quotes||[])}else toast(r.data?.detail||'Ошибка')}))})}
function loadQuotes(){return api('quotes').then(r=>renderQuotes(r.data?.quotes||[]))}
$('quoteAdd').onclick=()=>{const text=$('quoteInput').value.trim();if(!text)return toast('Введите текст цитаты');api('quotes',{method:'POST',body:{text}}).then(r=>{if(r.data?.ok){$('quoteInput').value='';renderQuotes(r.data.quotes||[]);toast('Цитата добавлена');haptic('light')}else toast(r.data?.detail||'Ошибка')})};$('quoteInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('quoteAdd').click()}});$('copyDiag').onclick=()=>{const b=state.boot||{},safe={app_version:b.app_version,status:b.status,sources:(b.sources||[]).map(x=>({source_name:x.source_name,source_type:x.source_type,is_online:x.is_online,last_seen_at:x.last_seen_at,agent_version:x.agent_version})),metrics:b.metrics,services:b.services};copyText(JSON.stringify(safe,null,2)).then(()=>toast('Диагностика скопирована'))};
$('configExportBtn').onclick=async()=>{const passphrase=$('configPassword').value;if(passphrase.length<8)return toast('Введите пароль не короче 8 символов');$('configExportBtn').disabled=true;try{const r=await api('config/export-encrypted',{method:'POST',body:{passphrase}});if(r.data?.format!=='xass-config-encrypted')throw new Error(r.data?.detail||'Не удалось зашифровать резервную копию');const url=URL.createObjectURL(new Blob([JSON.stringify(r.data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='xass-backup-'+new Date().toISOString().slice(0,10)+'.xass-backup';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Зашифрованная резервная копия готова')}catch(e){toast(e.message||'Ошибка экспорта')}finally{$('configExportBtn').disabled=false}};$('configImportBtn').onclick=()=>$('configImportFile').click();$('configImportFile').accept='.xass-backup,application/json,.json';$('configImportFile').onchange=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;const passphrase=$('configPassword').value;if(passphrase.length<8)return toast('Введите пароль от резервной копии');let bundle;try{bundle=JSON.parse(await file.text());if(bundle?.format!=='xass-config-encrypted'||Number(bundle?.version)!==1)throw new Error('Нужна зашифрованная резервная копия .xass-backup')}catch(e){return toast(e.message||'Файл повреждён')}try{const preview=await api('config/preview',{method:'POST',body:{passphrase,bundle}});if(!preview.data?.ok)throw new Error(preview.data?.detail||'Не удалось проверить копию');const p=preview.data.preview||{};$('configPreview').textContent='Будет заменено: профиль, проекты '+p.projects.incoming+', цитаты '+p.quotes.incoming+', сценарии '+p.scenarios.incoming+', автоматизации '+(p.rules?.incoming||0)+', правила уведомлений '+p.notification_rules+'. Текущие секреты останутся на сервере.';ask('Проверка завершена. Восстановить «'+file.name+'»? Пе