const PROFILE_DRAFT_KEY='xass-profile-draft-v1';function readProfileDraft(){try{return JSON.parse(localStorage.getItem(PROFILE_DRAFT_KEY)||'null')}catch(e){return null}}function applyProfileDraft(draft){const p=draft?.profile||{},c=draft?.site_config||{};for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])if(key in p)$(id).value=p[key]||'';$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');if(/^#[0-9a-f]{6}$/i.test(c.accent_color||''))$('siteAccent').value=c.accent_color;const widgets=new Set(c.widgets||[]);document.querySelectorAll('[data-site-widget]').forEach(input=>input.checked=widgets.has(input.dataset.siteWidget));setAvatarPreview($('siteAvatar').value);markProfileDirty();toast('Черновик восстановлен')}
function renderSite(data){state.site=data;const p=data.profile||{},c=data.site_config||{},widgets=new Set(c.widgets||['about','quotes','music','weather','projects','contacts']);for(const [id,key] of [['siteName','name'],['siteUsername','username'],['siteTitle','title'],['siteBio','bio'],['siteTelegram','telegram_url'],['siteAvatar','avatar_url'],['siteQuote','quote']])$(id).value=p[key]||'';setAvatarPreview(p.avatar_url);$('siteStack').value=(p.stack||[]).join(', ');$('siteLinks').value=(p.links||[]).map(x=>(x.label||'')+' | '+(x.url||'')).join('\n');$('siteAccent').value=/^#[0-9a-f]{6}$/i.test(c.accent_color||'')?c.accent_color:'#376dff';document.querySelectorAll('[data-site-widget]').forEach(input=>input.checked=widgets.has(input.dataset.siteWidget));updateProfilePreview();setProfileDirty(false);renderProjects(data.projects||[]);loadQuotes();const url=data.public_url||location.origin+'/profile.php';$('homeOpenSite').href=url}
function loadSite(){api('site').then(r=>{if(!r.data?.ok)return toast(r.data?.detail||'Ошибка сайта');renderSite(r.data);if(state.draftPrompted)return;state.draftPrompted=true;const draft=readProfileDraft();if(draft?.profile)ask('На этом устройстве найден черновик профиля. Восстановить его?',ok=>ok&&applyProfileDraft(draft))})}
function profilePayload(){return{name:$('siteName').value,username:$('siteUsername').value,title:$('siteTitle').value,bio:$('siteBio').value,telegram_url:$('siteTelegram').value,avatar_url:$('siteAvatar').value,quote:$('siteQuote').value,stack:$('siteStack').value.split(',').map(x=>x.trim()).filter(Boolean),links:$('siteLinks').value.split('\n').map(line=>{const parts=line.split('|');return{label:(parts.shift()||'').trim(),url:parts.join('|').trim()}}).filter(x=>x.label&&x.url)}}
function siteConfigPayload(){return{accent_color:$('siteAccent').value,widgets:[...document.querySelectorAll('[data-site-widget]:checked')].map(input=>input.dataset.siteWidget)}}
$('saveProfileBtn').onclick=async function(){this.disabled=true;this.textContent='Сохраняю…';try{const [profileResult,configResult]=await Promise.all([api('site/profile',{method:'POST',body:profilePayload()}),api('site/config',{method:'POST',body:siteConfigPayload()})]);if(!profileResult.data?.ok)throw new Error(profileResult.data?.detail||'Профиль не сохранён');if(!configResult.data?.ok)throw new Error(configResult.data?.detail||'Стиль не сохранён');state.site={...state.site,profile:profileResult.data.profile,site_config:configResult.data.site_config};localStorage.removeItem(PROFILE_DRAFT_KEY);setProfileDirty(false);updateProfilePreview();toast('Изменения опубликованы');haptic('medium')}catch(e){toast(e.message||'Не удалось сохранить изменения')}finally{this.disabled=false;this.textContent='Сохранить изменения'}};$('saveProfileDraftBtn').onclick=()=>{try{localStorage.setItem(PROFILE_DRAFT_KEY,JSON.stringify({saved_at:new Date().toISOString(),profile:profilePayload(),site_config:siteConfigPayload()}));toast('Черновик сохранён только на этом устройстве')}catch(e){toast('Не удалось сохранить черновик')}};$('discardProfileBtn').onclick=()=>{if(!state.profileDirty)return toast('Несохранённых изменений нет');ask('Отменить несохранённые изменения профиля?',ok=>{if(!ok)return;localStorage.removeItem(PROFILE_DRAFT_KEY);renderSite(state.site);toast('Изменения отменены')})};$('openSiteBtn').onclick=()=>{const url=state.site?.public_url||location.origin+'/profile.php';tg?.openLink?tg.openLink(url):window.open(url,'_blank')};
['siteName','siteUsername','siteTitle','siteBio','siteTelegram','siteAvatar','siteStack','siteLinks','siteAccent'].forEach(id=>$(id).addEventListener('input',markProfileDirty));document.querySelectorAll('[data-site-widget]').forEach(input=>input.addEventListener('change',markProfileDirty));
